3	// Group orders ({ id, date: 'YYYY-MM-DD', amount }) by month label.
4	export function monthlyTotals(orders) {
5	  const totals = {};
6	  for (const order of orders) {
7	    const label = monthLabel(order.date);
8	    totals[label] = (totals[label] ?? 0) + order.amount;
9	  }
10	  return totals;
11	}
